<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: #121a2f;
      --panel-2: #17213a;
      --text: #e8eefc;
      --muted: #9aa8c7;
      --border: #2a3552;
      --accent: #7c9cff;
      --accent-2: #9d7bff;
      --error: #ff7b7b;
      --shadow: 0 20px 60px rgba(0, 0, 0, 0.35);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top, rgba(124, 156, 255, 0.18), transparent 35%),
        linear-gradient(180deg, #080c17 0%, var(--bg) 100%);
      display: grid;
      place-items: center;
      padding: 24px;
    }

    .card {
      width: min(100%, 680px);
      background: linear-gradient(180deg, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.02)), var(--panel);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 24px;
      box-shadow: var(--shadow);
      padding: 32px;
    }

    .eyebrow {
      display: inline-block;
      color: var(--accent);
      font-size: 0.85rem;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      margin-bottom: 8px;
    }

    h1 {
      margin: 0 0 12px;
      font-size: clamp(2rem, 4vw, 2.7rem);
      line-height: 1.1;
    }

    p {
      margin: 0 0 28px;
      color: var(--muted);
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 18px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    label {
      font-weight: 600;
      font-size: 0.95rem;
    }

    input {
      width: 100%;
      border: 1px solid var(--border);
      background: var(--panel-2);
      color: var(--text);
      border-radius: 14px;
      padding: 14px 16px;
      font: inherit;
      transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
    }

    input::placeholder {
      color: #7381a5;
    }

    input:focus {
      outline: none;
      border-color: rgba(124, 156, 255, 0.85);
      box-shadow: 0 0 0 4px rgba(124, 156, 255, 0.18);
    }

    .helper-text {
      color: var(--muted);
      font-size: 0.88rem;
    }

    .error-message {
      min-height: 1.1em;
      color: var(--error);
      font-size: 0.88rem;
    }

    .form-field.invalid input {
      border-color: rgba(255, 123, 123, 0.95);
      box-shadow: 0 0 0 4px rgba(255, 123, 123, 0.12);
    }

    button {
      justify-self: start;
      border: 0;
      border-radius: 999px;
      padding: 14px 22px;
      background: linear-gradient(135deg, var(--accent), var(--accent-2));
      color: white;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      box-shadow: 0 12px 30px rgba(124, 156, 255, 0.25);
      transition: transform 0.2s ease, box-shadow 0.2s ease;
    }

    button:hover {
      transform: translateY(-1px);
      box-shadow: 0 16px 34px rgba(124, 156, 255, 0.32);
    }

    button:active {
      transform: translateY(0);
    }

    .status {
      margin-top: 8px;
      color: #8ef0b2;
      font-size: 0.95rem;
      min-height: 1.2em;
    }

    @media (max-width: 600px) {
      .card {
        padding: 22px;
        border-radius: 20px;
      }
    }
  </style>
</head>
<body>
  <main class="card">
    <span class="eyebrow">Support</span>
    <h1>Contact our team</h1>
    <p>Send us a message and we’ll get back to you as soon as possible.</p>

    <form id="support-form" novalidate>
      <div class="form-field" id="name-field">
        <label for="full-name">Full name</label>
        <input id="full-name" name="fullName" type="text" autocomplete="name" placeholder="Ada Lovelace" required />
        <div class="error-message" id="name-error" aria-live="polite"></div>
      </div>

      <div class="form-field" id="email-field">
        <label for="email-address">Email address</label>
        <input id="email-address" name="emailAddress" type="email" autocomplete="email" placeholder="ada@example.com" required />
        <div class="error-message" id="email-error" aria-live="polite"></div>
      </div>

      <div class="form-field" id="phone-field">
        <label for="phone-number">Phone number</label>
        <input id="phone-number" name="phoneNumber" type="tel" autocomplete="tel" placeholder="(555) 123-4567" />
        <div class="helper-text">Optional. Use a format like +1 555 123 4567 or (555) 123-4567.</div>
        <div class="error-message" id="phone-error" aria-live="polite"></div>
      </div>

      <button type="submit">Submit</button>
      <div class="status" id="form-status" aria-live="polite"></div>
    </form>
  </main>

  <script>
    const form = document.getElementById('support-form');
    const nameInput = document.getElementById('full-name');
    const emailInput = document.getElementById('email-address');
    const phoneInput = document.getElementById('phone-number');

    const fields = {
      name: document.getElementById('name-field'),
      email: document.getElementById('email-field'),
      phone: document.getElementById('phone-field')
    };

    const errors = {
      name: document.getElementById('name-error'),
      email: document.getElementById('email-error'),
      phone: document.getElementById('phone-error')
    };

    const status = document.getElementById('form-status');

    const phonePattern = /^\+?[0-9\s().-]{7,}$/;

    function setError(fieldKey, message) {
      fields[fieldKey].classList.toggle('invalid', Boolean(message));
      errors[fieldKey].textContent = message;
    }

    function validateName() {
      const value = nameInput.value.trim();
      if (!value) {
        setError('name', 'Full name is required.');
        return false;
      }
      setError('name', '');
      return true;
    }

    function validateEmail() {
      const value = emailInput.value.trim();
      if (!value) {
        setError('email', 'Email address is required.');
        return false;
      }
      if (!emailInput.checkValidity()) {
        setError('email', 'Enter a valid email address.');
        return false;
      }
      setError('email', '');
      return true;
    }

    function validatePhone() {
      const value = phoneInput.value.trim();
      if (!value) {
        setError('phone', '');
        return true;
      }
      if (!phonePattern.test(value)) {
        setError('phone', 'Enter a valid phone number or leave it blank.');
        return false;
      }
      setError('phone', '');
      return true;
    }

    function validateForm() {
      const validName = validateName();
      const validEmail = validateEmail();
      const validPhone = validatePhone();
      return validName && validEmail && validPhone;
    }

    [nameInput, emailInput, phoneInput].forEach((input) => {
      input.addEventListener('input', () => {
        if (input === nameInput) validateName();
        if (input === emailInput) validateEmail();
        if (input === phoneInput) validatePhone();
        status.textContent = '';
      });
      input.addEventListener('blur', () => {
        if (input === nameInput) validateName();
        if (input === emailInput) validateEmail();
        if (input === phoneInput) validatePhone();
      });
    });

    form.addEventListener('submit', (event) => {
      event.preventDefault();
      status.textContent = '';

      if (!validateForm()) {
        return;
      }

      status.textContent = 'Your message is ready to send.';
      form.reset();
      Object.keys(errors).forEach((key) => setError(key, ''));
    });
  </script>
</body>
</html>
